import { extractOutline } from "../services/navigation";

export function DocumentOutline(props: {
  content: string;
  onNavigate: (slug: string) => void;
}) {
  const items = extractOutline(props.content);

  return (
    <nav className="outline" aria-label="Sumário">
      <h2>Sumário</h2>
      {items.length === 0 ? (
        <p className="outline-empty">Nenhum heading no documento.</p>
      ) : (
        <ul>
          {items.map((it) => (
            <li key={it.id} style={{ marginLeft: (it.level - 1) * 12 }}>
              <button
                type="button"
                className="outline-link"
                onClick={() => props.onNavigate(it.id)}
              >
                {it.text}
              </button>
            </li>
          ))}
        </ul>
      )}
    </nav>
  );
}
